begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(24);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp181@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18100000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18100000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18100000-0000-0000-0000-000000000004','18100000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18100000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18100000-0000-0000-0000-000000000005','18100000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('18100000-0000-0000-0000-000000000006','18100000-0000-0000-0000-000000000002','Synthetic client');
insert into public.staffs(id,organization_id,name) values ('18100000-0000-0000-0000-000000000007','18100000-0000-0000-0000-000000000002','Synthetic staff');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18100000-0000-0000-0000-000000000009','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp-recipient@example.invalid','x',now(),now());
insert into public.organization_members(organization_id,user_id,role) values ('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000009','member');
update public.staffs set user_id='18100000-0000-0000-0000-000000000009' where id='18100000-0000-0000-0000-000000000007';

insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18100000-0000-0000-0000-000000000008','18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000006','2026-11-01 00:00+00','2026-11-01 01:00+00','published');
insert into private.mcp_shift_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
insert into private.mcp_person_search_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000005"}',true);
insert into private.mcp_shift_update_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('mcp180-browser','mcp180-browser','18100000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
set constraints all immediate;
set constraints all deferred;
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp180-browser"}',true);
select is(public.get_mcp_business_alert_preferences('18100000-0000-0000-0000-000000000002')->>'enabled','false','notifications disabled by default');
select public.set_mcp_business_alert_preferences('18100000-0000-0000-0000-000000000002',true,'daily',true,true);
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000005"}',true);
select is(public.get_mcp_business_alert_status('18100000-0000-0000-0000-000000000002')->>'enabled','true','MCP can read only its own preferences');
select throws_ok($$select public.get_mcp_business_alert_status('18100000-0000-0000-0000-000000000099')$$,'42501','permission_denied','MCP cannot read another organization');
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp180-browser"}',true);
insert into public.reports(id,client_id,helper_id,start_at,end_at,service_date,status)
 values('18100000-0000-0000-0000-000000000040','18100000-0000-0000-0000-000000000006','18100000-0000-0000-0000-000000000001','2026-11-01 00:00+00','2026-11-01 01:00+00','2026-11-01','pending');
select is(private.dispatch_mcp_business_alerts('2026-11-01 00:00+00')->>'created','2','pending and unassigned notifications delivered');
select is((select count(*) from public.notifications where user_id='18100000-0000-0000-0000-000000000001' and event_type like 'business.%'),2::bigint,'only recipient receives two business notifications');
select is(private.dispatch_mcp_business_alerts('2026-11-01 01:00+00')->>'created','0','same-day retry does not duplicate');
select public.set_mcp_business_alert_preferences('18100000-0000-0000-0000-000000000002',true,'weekly',true,true);
select is(private.dispatch_mcp_business_alerts('2026-11-01 02:00+00')->>'created','0','frequency change cannot duplicate same-day notifications');
select is((select count(*) from public.notifications where event_type like 'business.%' and (content like '%Synthetic%' or title like '%Synthetic%')),0::bigint,'notification contains no synthetic person names');
select ok(not has_function_privilege('authenticated','private.dispatch_mcp_business_alerts(timestamptz,integer,uuid,uuid)','execute') and not has_function_privilege('service_role','private.dispatch_mcp_business_alerts(timestamptz,integer,uuid,uuid)','execute'),'dispatcher is not exposed to app roles');
select public.set_mcp_business_alert_preferences('18100000-0000-0000-0000-000000000002',false,'daily',true,true);
select is(private.dispatch_mcp_business_alerts('2026-11-02 00:00+00')->>'created','0','stopped subscription is not delivered');
select public.set_mcp_business_alert_preferences('18100000-0000-0000-0000-000000000002',true,'weekly',true,false);
select is(private.dispatch_mcp_business_alerts('2026-11-02 00:00+00')->>'created','1','weekly pending notification delivered');
select is(private.dispatch_mcp_business_alerts('2026-11-03 00:00+00')->>'created','0','weekly retry on next day does not duplicate');
select ok(has_function_privilege('care_business_alert_worker','public.run_mcp_business_alerts()','execute') and not has_function_privilege('care_business_alert_worker','private.dispatch_mcp_business_alerts(timestamptz,integer,uuid,uuid)','execute'),'worker has only its bounded entry point');
select ok(not has_table_privilege('care_business_alert_worker','public.reports','SELECT') and not has_table_privilege('care_business_alert_worker','public.notifications','SELECT'),'worker has no direct business table reads');
select ok(not has_function_privilege('mcp_import','public.run_mcp_business_alerts()','execute') and not has_function_privilege('authenticated','public.run_mcp_business_alerts()','execute'),'MCP and browser cannot run worker');
grant care_business_alert_worker to postgres;
set local role care_business_alert_worker;
select set_config('test.worker_result',public.run_mcp_business_alerts()::text,true);
reset role;
select is(current_setting('test.worker_result'),'1','dedicated role dispatches only eligible pending notification');
select is((select count(*) from public.notifications where event_type='business.pending_reports' and user_id='18100000-0000-0000-0000-000000000001'),3::bigint,'worker writes through existing notifications');
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000009","role":"authenticated","session_id":"mcp188-member"}',true);
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('mcp188-member','mcp188-member','18100000-0000-0000-0000-000000000009',now(),now()+interval '1 hour');
select throws_ok($$select public.set_mcp_business_alert_preferences('18100000-0000-0000-0000-000000000002',true,'daily',true,false)$$,'42501','permission_denied','member without approval permission cannot enable pending notifications');
select throws_ok($$select public.set_mcp_business_alert_preferences('18100000-0000-0000-0000-000000000099',true,'daily',true,false)$$,'42501','permission_denied','other organization rejected');
select is((select count(*) from public.notifications where user_id='18100000-0000-0000-0000-000000000009' and event_type like 'business.%'),0::bigint,'no business notification to unauthorized member');
insert into public.organization_roles(id,organization_id,name,permissions) values ('18100000-0000-0000-0000-000000000050','18100000-0000-0000-0000-000000000002','Assigned approver','{"records":{"approve":"assigned"},"management":{"reports":true}}');
insert into public.organization_member_roles(organization_id,user_id,role_id) values ('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000009','18100000-0000-0000-0000-000000000050');
select public.set_mcp_business_alert_preferences('18100000-0000-0000-0000-000000000002',true,'daily',true,false);
select is(private.dispatch_mcp_business_alerts('2026-11-04 00:00+00')->>'created','0','assigned approver does not receive another client notification');
insert into public.assignments(client_id,staff_id) values ('18100000-0000-0000-0000-000000000006','18100000-0000-0000-0000-000000000007');
select is(private.dispatch_mcp_business_alerts('2026-11-04 00:00+00')->>'created','1','assigned approver receives notification for assigned client');
select is((select count(*) from public.notifications where user_id='18100000-0000-0000-0000-000000000009' and event_type='business.pending_reports'),1::bigint,'only one assigned-client alert is emitted');
update public.organization_roles set permissions='{}' where id='18100000-0000-0000-0000-000000000050';
select is(private.dispatch_mcp_business_alerts('2026-11-05 00:00+00')->>'created','0','revoked approval permission stops subsequent delivery');
select * from finish();
rollback;
